import React from 'react';

import { showModal } from '@ui-kit/Modal';

import MedicamentModal from './index';
import { IMedicament } from '../../@types/medicaments.types';

export function addMedicamentModalAsync(): Promise<Omit<IMedicament, 'id'>> {
  return new Promise((resolve) => {
    showModal({
      title: 'Добавление',
      children: (closeHandler: () => void) => (
        <MedicamentModal
          onAdd={(bp) => {
            resolve(bp);
            closeHandler();
          }}
          onCancel={closeHandler}
        />
      ),
    });
  });
}

export function editMedicamentModalAsync(m: IMedicament): Promise<IMedicament> {
  return new Promise((resolve) => {
    showModal({
      title: 'Редактирование',
      children: (closeHandler: () => void) => (
        <MedicamentModal
          data={m}
          onEdit={(bp) => {
            resolve(bp);
            closeHandler();
          }}
          onCancel={closeHandler}
        />
      ),
    });
  });
}
